export function checkBlobField(): boolean {
  const container = document.getElementById('container') as HTMLInputElement
  return container?.value.length > 0
}

function maybeShowInvalidUrlErrorMessage(blobUrlFormGroupElement: HTMLElement, showError: boolean) {
  const errorMessageElement = document.getElementById('blob-error-message')
  const show = 'display: flex !important'
  const hide = 'display: none !important'

  if (showError) {
    blobUrlFormGroupElement.classList.add('errored')
    errorMessageElement?.setAttribute('style', show)
  } else {
    blobUrlFormGroupElement.classList.remove('errored')
    errorMessageElement?.setAttribute('style', hide)
  }
}

export function autofillBlobContainerInput() {
  const blobUrlInputElement = document.getElementById('blob_sas_url_secret') as HTMLInputElement

  if (blobUrlInputElement) {
    blobUrlInputElement.addEventListener('input', e => {
      const target = e.target as HTMLInputElement
      if (target) {
        const blobUrlFormGroupElement = document.getElementsByClassName('form-group')[0] as HTMLElement
        if (target.value === '') {
          maybeShowInvalidUrlErrorMessage(blobUrlFormGroupElement, false)
          return
        }
        const blobUrl = new URL(target.value.trim(), window.location.origin)
        const isValidBlobUrl = blobUrl.host.endsWith('.blob.core.windows.net') && blobUrl.pathname !== ''
        if (isValidBlobUrl) {
          maybeShowInvalidUrlErrorMessage(blobUrlFormGroupElement, false)
          const blobContainerName = blobUrl.pathname.slice(1)
          const blobContainerInputElement = document.getElementById('container') as HTMLInputElement
          blobContainerInputElement.value = blobContainerName
        } else {
          maybeShowInvalidUrlErrorMessage(blobUrlFormGroupElement, true)
        }
      }
    })
  }
}
