import {observe} from '@github-ui/selector-observer'
import {serialize} from '@github-ui/form-utils'
import {checkSplunkFields} from './audit-log-streaming/splunk'
import {checkHubsField} from './audit-log-streaming/azure-hubs'
import {checkBlobField, autofillBlobContainerInput} from './audit-log-streaming/azure-blob'
import {checkGoogleCloudField} from './audit-log-streaming/google-cloud'
import {checkS3Fields, toggleS3Form} from './audit-log-streaming/s3'
import {flipEndpointLanguage} from './audit-log-streaming/helpers'
import {checkDatadogField, datadogSiteFieldListener} from './audit-log-streaming/datadog'

function maybeEnableButton(form: HTMLFormElement, button: HTMLButtonElement) {
  const loadForm = serialize(form)
  const inputs = form.querySelectorAll<HTMLInputElement>('input')
  for (const input of inputs) {
    input.addEventListener('input', function () {
      if (button.name === 'store_button') {
        const changesToSavedForm = serialize(form) !== loadForm
        button.disabled = changesToSavedForm
      } else if (button.name === 'check_button') {
        maybeEnableEndpointButton(button)
      }
    })
  }
}

function maybeEnableEndpointButton(button: HTMLButtonElement) {
  const inputNotEmpty = checkFormFields()
  if (inputNotEmpty) {
    button.disabled = false
    flipEndpointLanguage()
  } else {
    button.disabled = true
  }
}

function checkFormFields(): boolean {
  return (
    checkSplunkFields() ||
    checkHubsField() ||
    checkS3Fields() ||
    checkGoogleCloudField() ||
    checkBlobField() ||
    checkDatadogField()
  )
}

autofillBlobContainerInput()
toggleS3Form()
datadogSiteFieldListener(flipEndpointLanguage)

// Observe the save button
observe('.js-encrypt-bulk-submit-enable-empty', {
  add(form) {
    const saveButtonList = document.getElementsByName('store_button')
    if (!form || saveButtonList.length === 0 || (saveButtonList[0] as HTMLButtonElement).disabled) {
      return
    }
    maybeEnableButton(form as HTMLFormElement, saveButtonList[0] as HTMLButtonElement)
  },
})

// Observe the check endpoint button
observe('.js-encrypt-bulk-submit-enable-empty', {
  add(form) {
    const endpointButtonList = document.getElementsByName('check_button')
    if (!form || endpointButtonList.length === 0) {
      return
    }
    const inputNotEmpty = checkFormFields()
    const endpointButton = endpointButtonList[0] as HTMLButtonElement
    if (!inputNotEmpty) {
      endpointButton.disabled = true
    }
    maybeEnableButton(form as HTMLFormElement, endpointButton)
  },
})
